import { Injectable } from '@angular/core';

//-------[Setting up Pdfmake]--------|
import * as pdfMake from "pdfmake/build/pdfmake";
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
(<any>pdfMake).addVirtualFileSystem(pdfFonts);


import { UtilsService } from '../../utils.service';
import { UtilsService as UtilsContratos } from '../utils.service';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { UtilsEstadoCuentaService } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { ChronixPDFservice } from '../ChronixPDF.service';
import { Convenio } from '../../../models/convenio';

//--------[Injecting the necessary dependencies]--------|
@Injectable({
  providedIn: 'any',
})

export class convenioPagoPF {

  constructor(
    private utils: UtilsService,
    private utilsC: UtilsContratos,
    private creditoController: CreditoService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    private chronixPDF: ChronixPDFservice
  ) { }

  formatDecimals(value: number | undefined | null): string {
    const num = Number(value);

    if (isNaN(num)) return '00/100 MN';

    const decimalPart = Math.round((num % 1) * 100);
    const padded = decimalPart.toString().padStart(2, '0');

    return `${padded}/100 MN`;
  }

  async generarConvenioPagoPF(creditoParam: number | Credito | undefined, convenio?:Convenio|undefined) {
    let creditoID = this.utilsC.validarCreditoID(creditoParam);

    // Importing the necessary relations from the database to the variable
    const credito = await this.creditoController.find(creditoID, [
      "datosPersonaFisica",
      "datosPersonaFisica.datosPersonales",
      "datosPersonaFisica.datosPersonales.telefonosPersonales",
      "datosPersonaFisica.negocios",
      "productosFinancieros",
      "estadoCuenta",
      "abonos",
      "creditosPagos",
      "sucursales",
      "sesiones",
      "convenios",
      "convenios.conveniosPagos"
    ])

    if (!credito) return;

    const creditoOriginal = await this.creditoController.creditoOriginalFromReestructuradoS2c(credito)
    if (creditoOriginal) {
      credito.datos_persona_fisica = creditoOriginal.datos_persona_fisica
      credito.datos_personas_morales = creditoOriginal.datos_personas_morales
      credito.productos_financieros = creditoOriginal.productos_financieros
    }

    const convenioActivo = convenio ?? credito.convenios?.find(convenio => convenio.estatus == 'ACTIVO')
    if(convenio && !convenio.id){
      credito.convenios?.push(convenio)
    }

    console.log(convenioActivo)

    const tablaDP = credito.datos_persona_fisica?.datos_personales;
    const tablaEstadoCuenta = this.utilsEstadoCuenta.getEstadoCuentaPrevioAConvenio(credito);

    const telefonosCasa = this.utilsC.getTelefonosCasa(tablaDP?.telefonos_personales ?? [])
    const telefonosOficina = this.utilsC.getTelefonosOficina(tablaDP?.telefonos_personales ?? [])
    const telefonosCelular = this.utilsC.getTelefonosCelular(tablaDP?.telefonos_personales ?? [])

    const localidad = this.utils.municipioFromCredito(credito),
      fechaInicioConvenio = this.utilsC.fechaAletras(convenioActivo?.fecha_convenio),
      nombreAcreditado = this.utils.nombreClienteFromDatosPersonales(tablaDP),
      domicilioParticular = this.utils.domicilioFromDatosModel(tablaDP),
      tipoIdentificacion = tablaDP?.identificacion.toUpperCase().replace('INNE','INE'),
      numeroIdentificacion = tablaDP?.identificacion_numero.toUpperCase(),
      telefonoParticular = this.utilsC.combineTelefonosSacaUnNumero(telefonosCasa),
      telefonoOficina =  this.utilsC.combineTelefonosSacaUnNumero(telefonosCelular),
      liquidarSinMoratorios = tablaEstadoCuenta?.total_a_liquidar,
      liquidarSinMoratoriosConLetra = this.utilsC.NumeroALetras(liquidarSinMoratorios),
      saldoVencido = tablaEstadoCuenta?.saldo_vencido,
      saldoVencidoConLetra = this.utilsC.NumeroALetras(saldoVencido),
      folio = credito.folio,
      programa = credito.productos_financieros?.alias.toUpperCase()

    //Condicional para mostrar texto de compromiso al final del documento.   
    if(convenioActivo?.monto_abono_inicial) convenioActivo.monto_abono_inicial = +convenioActivo.monto_abono_inicial

    const textoCompromiso = !convenioActivo?.monto_abono_inicial ? {
      text: [
        'ME COMPROMETO A REALIZAR ',
        {text: convenioActivo?.plazo, bold: true},
        ' PAGOS MENSUALES PARA LLEVAR A CABO LA FIRMA DEL PRESENTE CONVENIO, PARA REALIZAR ',        
        {text: this.utilsC.generarDescripcionMensualidades(credito), bold: true},
      ]
    }
      : {
        text: [
          'ME COMPROMETO A REALIZAR ',
          { text: '1 (UN)', bold: true },
          ' PAGO MENSUAL POR LA CANTIDAD DE ',
          { text: '$' + this.utilsC.formatearNumeroConComas(convenioActivo?.monto_abono_inicial) + ' ', bold: true },
          { text: '(' + this.utilsC.NumeroALetras(convenioActivo?.monto_abono_inicial), bold: true },
          { text: this.utilsC.formatDecimals(convenioActivo?.monto_abono_inicial) + ')', bold: true },
          ' PARA LLEVAR A CABO LA FIRMA DEL PRESENTE CONVENIO, PARA POSTERIORMENTE REALIZAR ',
          ...this.utilsC.generarDescripcionMensualidades(credito),
          ' SIENDO CADA UNO DE ELLOS LOS ÚLTIMOS DÍAS DE CADA MES HASTA CULMINAR EL ADEUDO TOTAL ',
          'DEL CRÉDITO, INICIANDO EL PRIMERO DE ELLOS EL DÍA ',
          { text: this.utilsC.fechaAletras(convenioActivo?.fecha_inicio), bold: true },
          '.'
        ],
      };

    const generatedDocument: any = {
      pageMargins: [80, 50, 80, 50],
      content: [

        this.chronixPDF.generateTitle('CONVENIO DE PAGO PERSONA FISICA', '#7B001C', [`${localidad}, BAJA CALIFORNIA, ${fechaInicioConvenio}`]),
        // Introduccion
        {
          text: 'LIC. ALFONSO CHÁVEZ PÉREZ',
          bold: true,
          margin: [0, 0, 0, 5]
        },
        {
          text: [`DIRECTOR DEL FIDEICOMISO PARA EL DESARROLLO ECONÓMICO DE BAJA CALIFORNIA. SECRETARÍA DE ECONOMÍA E INNOVACIÓN`],
          alignment: 'left', fontSize: 11, bold: true
        },
        {
          text: 'P r e s e n t e.',
          margin: [0, 0, 0, 15]
        },
        {
          text: [
            '\nYO ',
            { text: nombreAcreditado, bold: true },
            ' CON DOMICILIO PARTICULAR EN ',
            { text: domicilioParticular, bold: true },
            ' QUIEN SE IDENTIFICA CON ',
            { text: tipoIdentificacion, bold: true },
            ', NÚMERO DE IDENTIFICACIÓN OFICIAL ',
            { text: numeroIdentificacion, bold: true },
            ...( !telefonosCasa.length ? [] : [
              ' Y NÚMERO PARTICULAR ',
              { text: telefonoParticular, bold: true },
            ]),
            ...( !telefonosCelular.length ? [] : [
              ', Y NÚMERO DE OFICINA ',
              { text: telefonoOficina, bold: true },
            ]),
            ' RECONOZCO MI ADEUDO POR LA CANTIDAD DE ',
            { text: '$' + this.utilsC.formatearNumeroConComas(liquidarSinMoratorios), bold: true },
            { text: ' (' + this.utilsC.NumeroALetras(liquidarSinMoratorios), bold: true },
            { text: " " + this.utilsC.formatDecimals(liquidarSinMoratorios) + ')', bold: true },
            ' COMO SALDO TOTAL, TENIENDO COMO SALDO VENCIDO LA CANTIDAD DE ',
            { text: '$ ' + this.utilsC.formatearNumeroConComas(saldoVencido), bold: true },
            { text: ' (' + saldoVencidoConLetra + " " + this.formatDecimals(saldoVencido) + ')', bold: true },
            ' SIENDO BENEFICIARIO DEL CRÉDITO ',
            { text: folio, bold: true },
            ' DEL PROGRAMA ',
            { text: programa + '.', bold: true },
            '\n\n'
          ],
          alignment: 'justify',
          fontSize: 10
        },
        {
          text: textoCompromiso,
          fontSize: 10,
          alignment: 'justify'
        },
        { text: 'SIN MÁS POR EL MOMENTO QUEDO A SUS ÓRDENES.', alignment: "left", margin: [0, 20, 0, 0], fontSize: 10 },
        { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 200, y2: 0, lineWidth: 1, lineColor: '#000000' }], margin: [0, 80, 0, 10], alignment: "center" },
        {
          text: `C. ${nombreAcreditado}`,
          alignment: "center",
          bold: true
        },
        {
          text: `ACREDITADO`,
          alignment: "center"
        }
      ]
    }
    pdfMake.createPdf(generatedDocument).open();
  }
}
