  getPagosFromActiveConvenios(credito: Credito): ConvenioPago[] {
    return credito.convenios
      ?.filter(convenio => convenio.estatus === 'ACTIVO')
      .flatMap(convenio => convenio.convenios_pagos ?? [])
      ?? []
  }


  sortPagosByFecha(pagos: ConvenioPago[]): ConvenioPago[] {
    return pagos.sort((a, b) => new Date(a.fecha).getTime() - new Date(b.fecha).getTime());
  }

  roundTwo(num: number): number {
    const precisionFix = Math.round((num + Number.EPSILON) * 1e10) / 1e10;

    // If the number is close enough to 0 (between -0.01 and 0.01), return 0
    if (precisionFix > -0.01 && precisionFix < 0.01) {
      return 0.00;
    }

    // Otherwise, round to 2 decimals normally
    return Math.round(precisionFix * 100) / 100;
  }

  formatDecimals(value: number | undefined | null): string {
    const num = Number(value);

    if (isNaN(num)) return '00/100 MN';

    const decimalPart = Math.round((num % 1) * 100);
    const padded = decimalPart.toString().padStart(2, '0');

    return `${padded}/100 MN`;
  }

